CREATE TABLE `inventory_transactions` (
  `TransactionID` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `Date` datetime DEFAULT NULL,
  `ProductID` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `TransactionType` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Quantity` bigint DEFAULT NULL,
  `BatchNumber` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `SupplierID` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `WarehouseLocation` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ExpiryDate` datetime DEFAULT NULL,
  `UnitCost` double DEFAULT NULL,
  `EmployeeID` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Referencepo` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ReasonCode` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `StockLevelAfter` bigint DEFAULT NULL,
  PRIMARY KEY (`TransactionID`),
  KEY `fk_inventory_product` (`ProductID`),
  KEY `fk_inventory_supplier` (`SupplierID`),
  KEY `fk_inventory_po` (`Referencepo`),
  CONSTRAINT `fk_inventory_po` FOREIGN KEY (`Referencepo`) REFERENCES `purchase_orders` (`PO_ID`),
  CONSTRAINT `fk_inventory_product` FOREIGN KEY (`ProductID`) REFERENCES `products_master` (`ProductID`),
  CONSTRAINT `fk_inventory_supplier` FOREIGN KEY (`SupplierID`) REFERENCES `suppliers` (`SupplierID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
