--
-- Table structure for table `purchase_orders`
--

DROP TABLE IF EXISTS `purchase_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchase_orders` (
  `PO_ID` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `OrderDate` datetime DEFAULT NULL,
  `SupplierID` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ProductID` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `OrderQuantity` bigint DEFAULT NULL,
  `UnitCost` double DEFAULT NULL,
  `TotalCost` double DEFAULT NULL,
  `ExpectedDelivery` datetime DEFAULT NULL,
  `ActualDelivery` datetime DEFAULT NULL,
  `Status` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`PO_ID`),
  KEY `fk_po_supplier` (`SupplierID`),
  KEY `fk_po_product` (`ProductID`),
  CONSTRAINT `fk_po_product` FOREIGN KEY (`ProductID`) REFERENCES `products_master` (`ProductID`),
  CONSTRAINT `fk_po_supplier` FOREIGN KEY (`SupplierID`) REFERENCES `suppliers` (`SupplierID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

