CREATE TABLE `sales` (
  `SaleID` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `Date` datetime DEFAULT NULL,
  `ProductID` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Quantity` bigint DEFAULT NULL,
  `SellingPrice` double DEFAULT NULL,
  `TotalAmount` double DEFAULT NULL,
  `CustomerType` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `PaymentMethod` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `PrescriptionID` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `EmployeeID` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `DiscountPercentage` double DEFAULT NULL,
  `IsInsuranceClaim` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`SaleID`),
  KEY `fk_sales_product` (`ProductID`),
  CONSTRAINT `fk_sales_product` FOREIGN KEY (`ProductID`) REFERENCES `products_master` (`ProductID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
