DROP TABLE IF EXISTS `suppliers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `suppliers` (
  `SupplierID` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `SupplierName` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Category` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Country` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `LeadTimeDays` bigint DEFAULT NULL,
  `QualityRating` double DEFAULT NULL,
  `PaymentTerms` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ContactPerson` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Email` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Phone` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `IsActive` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`SupplierID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

